// Version changes require a fresh choice. No analytics ID is generated by SingMotion.
export const CONSENT_KEY = "sm_analytics_consent_v1";
export const CONSENT_VERSION = 1;
export const CONSENT_TTL = 180 * 24 * 60 * 60 * 1000;
export type Choice = "granted" | "denied";
export type Consent = { version: number; choice: Choice; at: number };
export function readConsent(raw: string | null, now = Date.now()): Choice | null {
  try {
    if (!raw) return null;
    const value: unknown = JSON.parse(raw);
    if (!value || typeof value !== "object") return null;
    const record = value as Partial<Consent>;
    if (record.version !== CONSENT_VERSION || typeof record.at !== "number" ||
        !Number.isFinite(record.at) || record.at > now || now - record.at >= CONSENT_TTL) return null;
    return record.choice === "granted" || record.choice === "denied" ? record.choice : null;
  } catch { return null; }
}
export function serializeConsent(choice: Choice, now = Date.now()) {
  return JSON.stringify({ version: CONSENT_VERSION, choice, at: now });
}
export function analyticsConfig(env: Record<string, string | undefined>) {
  const stage = env.RAILWAY_ENVIRONMENT_NAME === "staging";
  const production = env.RAILWAY_ENVIRONMENT_NAME === "production";
  const id = env.GA4_MEASUREMENT_ID ?? "";
  const enabled = (stage || production) && env.GA4_ENABLED === "true" && /^G-[A-Z0-9]{4,20}$/.test(id);
  return { id: enabled ? id : null, preview: stage && env.GA4_CONSENT_PREVIEW === "true" };
}
// Exact public marketing routes only. No dynamic customer/project IDs, query strings or hashes.
const publicPages: Record<string, string> = {
  "/": "SingMotion AI", "/help": "Help", "/help/camera-movements": "Camera movements",
  "/help/ai-video-guides": "AI video guides", "/help/ai-video-generator": "AI video generator",
  "/help/ai-music-video-maker": "Music video generator", "/help/tiktok-reels-shorts": "Short video generator",
  "/help/omnihuman-ai-video": "OmniHuman video",
};
export function publicAnalyticsPage(pathname: string): string | null {
  return Object.hasOwn(publicPages, pathname) ? publicPages[pathname] : null;
}
export function sanitizedReferrer(referrer: string): string {
  try {
    const url = new URL(referrer);
    return url.protocol === "https:" || url.protocol === "http:" ? url.origin + "/" : "";
  } catch { return ""; }
}
